#!/system/bin/sh
# Magisk M3 Module Template - service.sh
# Executed late in the boot process (late_start service mode)

MODDIR=${0%/*}
LOGFILE="$MODDIR/service.log"

log() {
    echo "[$(date '+%Y-%m-%d %H:%M:%S')] $1" >> "$LOGFILE"
}

# Wait for boot completion
until [ "$(getprop sys.boot_completed)" = "1" ]; do
    sleep 2
done

# Initialize or rotate log
[ -f "$LOGFILE" ] && [ $(wc -c < "$LOGFILE") -gt 1048576 ] && mv "$LOGFILE" "$LOGFILE.old"
log "=== Magisk M3 Template Service Initialized ==="

# Source user configuration generated by Companion App
if [ -f "$MODDIR/config.sh" ]; then
    . "$MODDIR/config.sh"
    log "Config loaded successfully: FEATURE_ENABLED=$FEATURE_ENABLED, BOOST_MODE=$BOOST_MODE"
else
    log "Warning: config.sh not found, using default parameters"
    FEATURE_ENABLED=1
    BOOST_MODE="balanced"
fi

if [ "$FEATURE_ENABLED" != "1" ]; then
    log "Module features are disabled in config.sh. Exiting service."
    exit 0
fi

# Apply Governor / Boost Mode Example
case "$BOOST_MODE" in
    "powersave")
        log "Applying Powersave Profile..."
        for gov in /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor; do
            [ -f "$gov" ] && echo "powersave" > "$gov" 2>/dev/null
        done
        ;;
    "performance"|"extreme")
        log "Applying High Performance Profile ($BOOST_MODE)..."
        for gov in /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor; do
            [ -f "$gov" ] && echo "performance" > "$gov" 2>/dev/null
        done
        ;;
    *)
        log "Applying Balanced Profile (schedutil / default)..."
        for gov in /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor; do
            [ -f "$gov" ] && echo "schedutil" > "$gov" 2>/dev/null
        done
        ;;
esac

# Apply Touch Sampling Rate Example
if [ -n "$TOUCH_SAMPLING_RATE" ]; then
    log "Setting touch sampling frequency target: ${TOUCH_SAMPLING_RATE}Hz"
    # Example prop or sysfs trigger
    resetprop -n persist.vendor.touch.sampling_rate "$TOUCH_SAMPLING_RATE" 2>/dev/null
fi

# Apply Custom User Arguments
if [ -n "$CUSTOM_ARGS" ]; then
    log "Executing custom args: $CUSTOM_ARGS"
fi

log "Service startup sequence completed successfully."
